const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'cover',
  index: 1,
  title: "Generative AI's Act Two"
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: "2b2d42" };

  // Left decorative accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.08, h: 5.625,
    fill: { color: theme.accent }
  });

  // Large decorative "2" in background (Act Two)
  slide.addText("2", {
    x: 6.5, y: 0.3, w: 3.5, h: 4.5,
    fontSize: 200, fontFace: "Georgia",
    color: "3d3f5c", bold: true,
    align: "center", valign: "middle",
    transparency: 60
  });

  // Accent line
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 1.4, w: 1.2, h: 0.06,
    fill: { color: theme.accent }
  });

  // Main title
  slide.addText("Generative AI's Act Two", {
    x: 0.6, y: 1.6, w: 8, h: 1.2,
    fontSize: 44, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "left", valign: "top",
    margin: 0
  });

  // Subtitle
  slide.addText("From Technology Hammer to Real Value", {
    x: 0.6, y: 2.85, w: 7, h: 0.6,
    fontSize: 22, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left", valign: "top",
    margin: 0
  });

  // Attribution and date
  slide.addText([
    { text: "Sequoia Capital", options: { bold: true, color: "FFFFFF", fontSize: 14, fontFace: "Calibri" } },
    { text: "  |  ", options: { color: theme.secondary, fontSize: 14, fontFace: "Calibri" } },
    { text: "September 2023", options: { color: theme.secondary, fontSize: 14, fontFace: "Calibri" } }
  ], {
    x: 0.6, y: 4.6, w: 5, h: 0.4,
    align: "left", valign: "middle", margin: 0
  });

  // Authors
  slide.addText("Sonya Huang  ·  Pat Grady  ·  GPT-4", {
    x: 0.6, y: 5.0, w: 5, h: 0.3,
    fontSize: 11, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left", valign: "top", margin: 0
  });

  // Bottom accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.4, w: 10, h: 0.225,
    fill: { color: "ef233c", transparency: 30 }
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "2b2d42", secondary: "8d99ae", accent: "ef233c", light: "edf2f4", bg: "edf2f4" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-01-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

