const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  subtype: 'timeline',
  index: 2,
  title: 'Six Decades of Technological Progress Converged to Enable Generative AI'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Six Decades of Technological Progress Converged to Enable Generative AI", {
    x: 0.5, y: 0.3, w: 9, h: 0.8,
    fontSize: 22, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", valign: "middle",
    margin: 0, fit: "shrink"
  });

  // Subtitle
  slide.addText("Three foundational waves accumulated over decades to create the conditions for generative AI", {
    x: 0.5, y: 1.05, w: 9, h: 0.4,
    fontSize: 12, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left", valign: "top", margin: 0
  });

  // Timeline axis line
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.7, w: 9, h: 0.02,
    fill: { color: theme.secondary, transparency: 40 }
  });

  // Wave 1: Moore's Law (6 decades) — widest bar
  const barY = 1.7;
  const barH = 0.85;
  const maxW = 8.5;
  const startX = 0.5;

  // Moore's Law bar — 6 decades
  slide.addShape(pres.shapes.RECTANGLE, {
    x: startX, y: barY, w: maxW, h: barH,
    fill: { color: theme.primary, transparency: 10 }
  });
  slide.addText([
    { text: "Moore's Law", options: { bold: true, fontSize: 16, fontFace: "Georgia", color: "FFFFFF" } },
    { text: "\n6 decades of compute", options: { bold: false, fontSize: 11, fontFace: "Calibri", color: "d0d3e0", breakLine: true } },
    { text: "Exaflops of processing power", options: { bold: false, fontSize: 10, fontFace: "Calibri", color: "a0a3b8" } }
  ], {
    x: startX + 0.2, y: barY, w: maxW - 0.4, h: barH,
    valign: "middle", margin: 0
  });

  // Internet bar — 4 decades (2/3 width)
  const internetW = (4 / 6) * maxW;
  const bar2Y = barY + barH + 0.15;
  slide.addShape(pres.shapes.RECTANGLE, {
    x: startX, y: bar2Y, w: internetW, h: barH,
    fill: { color: "8d99ae", transparency: 0 }
  });
  slide.addText([
    { text: "The Internet", options: { bold: true, fontSize: 16, fontFace: "Georgia", color: "FFFFFF" } },
    { text: "\n4 decades of training data", options: { bold: false, fontSize: 11, fontFace: "Calibri", color: "e8eaf0", breakLine: true } },
    { text: "Trillions of tokens produced (accelerated by COVID)", options: { bold: false, fontSize: 10, fontFace: "Calibri", color: "c8cad5" } }
  ], {
    x: startX + 0.2, y: bar2Y, w: internetW - 0.4, h: barH,
    valign: "middle", margin: 0
  });

  // Mobile/Cloud bar — 2 decades (1/3 width)
  const mobileW = (2 / 6) * maxW;
  const bar3Y = bar2Y + barH + 0.15;
  slide.addShape(pres.shapes.RECTANGLE, {
    x: startX, y: bar3Y, w: mobileW, h: barH,
    fill: { color: theme.accent }
  });
  slide.addText([
    { text: "Mobile & Cloud", options: { bold: true, fontSize: 16, fontFace: "Georgia", color: "FFFFFF" } },
    { text: "\n2 decades of distribution", options: { bold: false, fontSize: 11, fontFace: "Calibri", color: "ffd5d8", breakLine: true } },
    { text: "Supercomputer in every palm", options: { bold: false, fontSize: 10, fontFace: "Calibri", color: "ffb3b8" } }
  ], {
    x: startX + 0.2, y: bar3Y, w: mobileW - 0.4, h: barH,
    valign: "middle", margin: 0
  });

  // Spark icon / convergence callout
  slide.addShape(pres.shapes.OVAL, {
    x: 9.1, y: 4.35, w: 0.5, h: 0.5,
    fill: { color: theme.accent }
  });
  slide.addText("✦", {
    x: 9.1, y: 4.35, w: 0.5, h: 0.5,
    fontSize: 18, fontFace: "Arial", color: "FFFFFF",
    align: "center", valign: "middle"
  });

  // Convergence label
  slide.addText("Convergence → Generative AI", {
    x: 6.5, y: 4.45, w: 2.5, h: 0.3,
    fontSize: 11, fontFace: "Calibri",
    color: theme.primary, bold: true, align: "right", valign: "middle", margin: 0
  });

  // Timeline decade markers
  const decades = ["1960s", "1970s", "1980s", "1990s", "2000s", "2010s", "2020s"];
  decades.forEach((dec, i) => {
    const xPos = startX + (i * maxW / 6);
    slide.addText(dec, {
      x: xPos - 0.2, y: 4.75, w: 0.5, h: 0.25,
      fontSize: 8, fontFace: "Calibri",
      color: theme.secondary, bold: false, align: "center", valign: "top"
    });
    // Tick mark
    slide.addShape(pres.shapes.RECTANGLE, {
      x: xPos, y: 4.65, w: 0.01, h: 0.1,
      fill: { color: theme.secondary, transparency: 40 }
    });
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("2", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial", color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "2b2d42", secondary: "8d99ae", accent: "ef233c", light: "edf2f4", bg: "edf2f4" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-02-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

