const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  subtype: 'data-visualization',
  index: 3,
  title: 'GenAI Startups Surpassed $1B Revenue Faster Than SaaS Ever Did'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("GenAI Startups Surpassed $1B Revenue Faster Than SaaS Ever Did", {
    x: 0.5, y: 0.3, w: 9, h: 0.7,
    fontSize: 21, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", valign: "middle",
    margin: 0, fit: "shrink"
  });

  // Large stat callout
  slide.addText(">$1B", {
    x: 0.5, y: 1.2, w: 3.5, h: 1.4,
    fontSize: 72, fontFace: "Georgia",
    color: theme.accent, bold: true, align: "left", valign: "middle", margin: 0
  });
  slide.addText("startup revenue in months\nvs. years for SaaS", {
    x: 0.5, y: 2.55, w: 3.5, h: 0.6,
    fontSize: 13, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left", valign: "top", margin: 0
  });

  // Vertical divider
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 4.3, y: 1.2, w: 0.02, h: 2.8,
    fill: { color: theme.secondary, transparency: 50 }
  });

  // Three standout cards
  const cards = [
    {
      name: "ChatGPT",
      desc: "Fastest-growing application in history",
      stat: "Strong PMF among students & developers",
      color: theme.primary
    },
    {
      name: "Midjourney",
      desc: "Hundreds of millions in revenue",
      stat: "With just 11 employees",
      color: "8d99ae"
    },
    {
      name: "Character.ai",
      desc: "AI entertainment & companionship",
      stat: "2-hour avg. session time",
      color: theme.accent
    }
  ];

  const cardX = 4.6;
  const cardW = 5.0;
  const cardH = 0.85;
  const cardGap = 0.1;

  cards.forEach((card, i) => {
    const cy = 1.2 + i * (cardH + cardGap);

    // Card background
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cardX, y: cy, w: cardW, h: cardH,
      fill: { color: "FFFFFF" },
      shadow: { type: "outer", color: "000000", blur: 4, offset: 1, angle: 135, opacity: 0.08 }
    });

    // Left accent bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cardX, y: cy, w: 0.06, h: cardH,
      fill: { color: card.color }
    });

    // Company name
    slide.addText(card.name, {
      x: cardX + 0.25, y: cy + 0.08, w: cardW - 0.4, h: 0.3,
      fontSize: 15, fontFace: "Georgia",
      color: theme.primary, bold: true, align: "left", valign: "middle", margin: 0
    });

    // Description
    slide.addText(card.desc, {
      x: cardX + 0.25, y: cy + 0.35, w: cardW - 0.4, h: 0.22,
      fontSize: 11, fontFace: "Calibri",
      color: theme.primary, bold: false, align: "left", valign: "middle", margin: 0
    });

    // Stat highlight
    slide.addText(card.stat, {
      x: cardX + 0.25, y: cy + 0.55, w: cardW - 0.4, h: 0.22,
      fontSize: 10, fontFace: "Calibri",
      color: theme.secondary, bold: false, align: "left", valign: "middle", margin: 0
    });
  });

  // Bottom context note
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.3, w: 9, h: 0.6,
    fill: { color: "2b2d42", transparency: 90 }
  });
  slide.addText("Despite the rapid commercial traction, many AI companies still lack product-market fit or sustainable competitive advantage.", {
    x: 0.7, y: 4.3, w: 8.6, h: 0.6,
    fontSize: 10, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left", valign: "middle", margin: 0
  });

  // Source
  slide.addText("Source: Sequoia Capital analysis, 2023", {
    x: 0.5, y: 5.0, w: 4, h: 0.2,
    fontSize: 8, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left", valign: "middle"
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("3", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial", color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "2b2d42", secondary: "8d99ae", accent: "ef233c", light: "edf2f4", bg: "edf2f4" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-03-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

