const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  subtype: 'data-visualization',
  index: 4,
  title: 'AI-First Apps Show 14% Median Retention vs. 51% for Incumbents'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("AI-First Apps Show 14% Median Retention vs. 51% for Incumbents", {
    x: 0.5, y: 0.25, w: 9, h: 0.65,
    fontSize: 19, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", valign: "middle",
    margin: 0, fit: "shrink"
  });

  // Two side-by-side bar charts using PptxGenJS chart API

  // Incumbents chart (left)
  const incumbents = [
    { name: "WhatsApp", val: 85 },
    { name: "Instagram", val: 64 },
    { name: "YouTube", val: 64 },
    { name: "TikTok", val: 60 },
    { name: "Snapchat", val: 51 },
    { name: "Roblox", val: 41 },
    { name: "Tinder", val: 34 },
    { name: "Candy Crush", val: 32 },
    { name: "Duolingo", val: 30 }
  ];

  // AI-First chart (right)
  const aiFirst = [
    { name: "Character.ai", val: 41 },
    { name: "Runway", val: 27 },
    { name: "Remini", val: 14 },
    { name: "ChatGPT", val: 14 },
    { name: "Lensa", val: 12 }
  ];

  // Incumbents bar chart
  slide.addChart(pres.charts.BAR, [{
    name: "Retention %",
    labels: incumbents.map(d => d.name),
    values: incumbents.map(d => d.val)
  }], {
    x: 0.3, y: 1.0, w: 4.7, h: 3.4,
    barDir: "bar",
    chartColors: ["2b2d42"],
    showTitle: true,
    title: "Incumbents",
    titleColor: theme.primary,
    titleFontSize: 13,
    titleFontFace: "Georgia",
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: "2b2d42",
    dataLabelFontSize: 9,
    dataLabelFontFace: "Calibri",
    catAxisLabelColor: "2b2d42",
    catAxisLabelFontSize: 9,
    catAxisLabelFontFace: "Calibri",
    valAxisHidden: true,
    catGridLine: { style: "none" },
    valGridLine: { color: "d4d4d4", size: 0.5 },
    valAxisMaxVal: 100,
    showLegend: false,
    chartArea: { fill: { color: "FFFFFF" } }
  });

  // AI-First bar chart
  slide.addChart(pres.charts.BAR, [{
    name: "Retention %",
    labels: aiFirst.map(d => d.name),
    values: aiFirst.map(d => d.val)
  }], {
    x: 5.1, y: 1.0, w: 4.6, h: 3.4,
    barDir: "bar",
    chartColors: ["ef233c"],
    showTitle: true,
    title: "AI-First Companies",
    titleColor: theme.accent,
    titleFontSize: 13,
    titleFontFace: "Georgia",
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: "ef233c",
    dataLabelFontSize: 9,
    dataLabelFontFace: "Calibri",
    catAxisLabelColor: "2b2d42",
    catAxisLabelFontSize: 9,
    catAxisLabelFontFace: "Calibri",
    valAxisHidden: true,
    catGridLine: { style: "none" },
    valGridLine: { color: "d4d4d4", size: 0.5 },
    valAxisMaxVal: 100,
    showLegend: false,
    chartArea: { fill: { color: "FFFFFF" } }
  });

  // Median comparison callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.55, w: 9, h: 0.65,
    fill: { color: "2b2d42" }
  });

  slide.addText([
    { text: "Median Gap:  ", options: { bold: true, fontSize: 14, fontFace: "Georgia", color: "FFFFFF" } },
    { text: "Incumbents 51%", options: { bold: true, fontSize: 14, fontFace: "Calibri", color: "8d99ae" } },
    { text: "  vs.  ", options: { bold: false, fontSize: 12, fontFace: "Calibri", color: "8d99ae" } },
    { text: "AI-First 14%", options: { bold: true, fontSize: 14, fontFace: "Calibri", color: "ef233c" } },
    { text: "  — a 3.6× disadvantage", options: { bold: false, fontSize: 12, fontFace: "Calibri", color: "8d99ae" } }
  ], {
    x: 0.7, y: 4.55, w: 8.6, h: 0.65,
    align: "center", valign: "middle", margin: 0
