  const leftX = 0.5;
  const topY = 1.45;
  const cardW = 4.2;

  // Old approach label
  slide.addShape(pres.shapes.RECTANGLE, {
    x: leftX, y: topY, w: cardW, h: 0.45,
    fill: { color: theme.secondary }
  });
  slide.addText("ACT 1: By Model Modality", {
    x: leftX, y: topY, w: cardW, h: 0.45,
    fontSize: 12, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "center", valign: "middle", margin: 0
  });

  // Old categories
  const oldCategories = [
    { label: "Text Models", desc: "LLMs, chatbots" },
    { label: "Image Models", desc: "Image generation, editing" },
    { label: "Code Models", desc: "Code generation, completion" }
  ];

  oldCategories.forEach((cat, i) => {
    const cy = topY + 0.55 + i * 0.7;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: leftX, y: cy, w: cardW, h: 0.6,
      fill: { color: "FFFFFF" },
      shadow: { type: "outer", color: "000000", blur: 3, offset: 1, angle: 135, opacity: 0.05 }
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: leftX, y: cy, w: 0.05, h: 0.6,
