  slide.addShape(pres.shapes.RECTANGLE, {
    x: 4.7, y: 2.55, w: 0.6, h: 0.04,
    fill: { color: theme.accent }
  });
  // Arrow head (triangle approximation)
  slide.addText("▶", {
    x: 5.05, y: 2.35, w: 0.4, h: 0.4,
    fontSize: 14, fontFace: "Arial", color: theme.accent,
    align: "center", valign: "middle"
  });

  // Right column: "New Way" - Use Case
  const rightX = 5.3;

  slide.addShape(pres.shapes.RECTANGLE, {
    x: rightX, y: topY, w: cardW, h: 0.45,
    fill: { color: theme.accent }
  });
  slide.addText("ACT 2: By Use Case", {
    x: rightX, y: topY, w: cardW, h: 0.45,
    fontSize: 12, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "center", valign: "middle", margin: 0
  });

  // New categories with exemplars
  const newCategories = [
    { label: "Legal", desc: "Harvey — Custom LLMs for elite law firms", color: theme.accent },
    { label: "Enterprise Search", desc: "Glean — Indexing workspaces for relevant AI", color: theme.accent },
    { label: "Companionship", desc: "Character & Ava — Digital companions", color: theme.accent }
  ];

  newCategories.forEach((cat, i) => {
    const cy = topY + 0.55 + i * 0.7;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: rightX, y: cy, w: cardW, h: 0.6,
      fill: { color: "FFFFFF" },
      shadow: { type: "outer", color: "000000", blur: 3, offset: 1, angle: 135, opacity: 0.05 }
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: rightX, y: cy, w: 0.05, h: 0.6,
      fill: { color: cat.color }
    });
    slide.addText(cat.label, {
      x: rightX + 0.2, y: cy + 0.05, w: cardW - 0.3, h: 0.25,
      fontSize: 12, fontFace: "Georgia", color: theme.primary, bold: true, align: "left", valign: "middle", margin: 0
    });
    slide.addText(cat.desc, {
      x: rightX + 0.2, y: cy + 0.3, w: cardW - 0.3, h: 0.2,
      fontSize: 10, fontFace: "Calibri", color: theme.secondary, bold: false, align: "left", valign: "middle", margin: 0
    });
  });

  // Bottom insight bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.0, w: 9, h: 1.2,
    fill: { color: "2b2d42" }
  });
  slide.addText("This reorganization mirrors the broader Act 1 → Act 2 transition", {
    x: 0.7, y: 4.05, w: 8.6, h: 0.35,
    fontSize: 13, fontFace: "Georgia", color: "FFFFFF", bold: true, align: "left", valign: "middle", margin: 0
  });
  slide.addText("Applications are increasingly multi-modal, crossing text, image, and code boundaries. Organizing by use case reflects how value is actually delivered to customers — not how the underlying model processes data.", {
    x: 0.7, y: 4.4, w: 8.6, h: 0.7,
    fontSize: 11, fontFace: "Calibri", color: "8d99ae", bold: false, align: "left", valign: "top", margin: 0
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("7", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial", color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "2b2d42", secondary: "8d99ae", accent: "ef233c", light: "edf2f4", bg: "edf2f4" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-07-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

