const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'summary',
  index: 8,
  title: 'Key Takeaways: What Separates Winners in Act Two'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: "2b2d42" };

  // Title
  slide.addText("Key Takeaways", {
    x: 0.5, y: 0.3, w: 9, h: 0.6,
    fontSize: 30, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "left", valign: "middle", margin: 0
  });

  // Subtitle
  slide.addText("What Separates Winners in Act Two", {
    x: 0.5, y: 0.85, w: 9, h: 0.4,
    fontSize: 16, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left", valign: "middle", margin: 0
  });

  // Five takeaway items
  const takeaways = [
    {
      num: "1",
      title: "Retention is the critical challenge",
      desc: "AI-first apps at 14% median retention vs. 51% for incumbents — a 3.6× disadvantage"
    },
    {
      num: "2",
      title: "Foundation models should be a component, not the whole product",
      desc: "Thin wrappers lose; comprehensive, workflow-integrated solutions win"
    },
    {
      num: "3",
      title: "Multi-modal, workflow-integrated solutions will win",
      desc: "New editing interfaces and multi-modal capabilities make products stickier"
    },
    {
      num: "4",
      title: "The $1B+ revenue milestone proves real demand exists",
      desc: "Despite hype-cycle skepticism, generative AI has had a more successful commercial start than SaaS"
    },
    {
      num: "5",
      title: "Companies solving end-to-end human problems will define Act 2",
      desc: "The shift from technology-out to customer-back is the defining transition"
    }
  ];

  const startY = 1.5;
  const itemH = 0.72;
  const gap = 0.08;

  takeaways.forEach((item, i) => {
    const iy = startY + i * (itemH + gap);

    // Number badge
    slide.addShape(pres.shapes.OVAL, {
      x: 0.5, y: iy + 0.08, w: 0.38, h: 0.38,
      fill: { color: theme.accent }
    });
    slide.addText(item.num, {
      x: 0.5, y: iy + 0.08, w: 0.38, h: 0.38,
      fontSize: 14, fontFace: "Georgia", color: "FFFFFF", bold: true,
      align: "center", valign: "middle"
    });

    // Title
    slide.addText(item.title, {
      x: 1.1, y: iy + 0.02, w: 8.2, h: 0.3,
      fontSize: 14, fontFace: "Georgia",
      color: "FFFFFF", bold: true, align: "left", valign: "middle", margin: 0
    });

    // Description
    slide.addText(item.desc, {
      x: 1.1, y: iy + 0.32, w: 8.2, h: 0.3,
      fontSize: 11, fontFace: "Calibri",
      color: "8d99ae", bold: false, align: "left", valign: "middle", margin: 0
    });
  });

  // Bottom attribution bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.25, w: 10, h: 0.375,
    fill: { color: "ef233c", transparency: 80 }
  });
  slide.addText("Sequoia Capital  |  September 2023", {
    x: 0.5, y: 5.25, w: 5, h: 0.375,
    fontSize: 10, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left", valign: "middle", margin: 0
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("8", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial", color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "2b2d42", secondary: "8d99ae", accent: "ef233c", light: "edf2f4", bg: "edf2f4" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-08-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

